package com.boutique.shipping.messaging;import com.boutique.shipping.service.ShipmentService;import tools.jackson.databind.ObjectMapper;import org.springframework.amqp.rabbit.annotation.RabbitListener;import org.springframework.kafka.annotation.KafkaListener;import org.springframework.stereotype.Component;import java.util.UUID;
@Component public class OrderConfirmedListener{private final ShipmentService service;private final ObjectMapper json;public OrderConfirmedListener(ShipmentService s,ObjectMapper j){service=s;json=j;}@KafkaListener(topics="${app.kafka.order-events-topic}",groupId="${spring.kafka.consumer.group-id}")public void kafka(String payload)throws Exception{handle(payload);}@RabbitListener(queues="boutique.shipping.order-confirmed")public void rabbit(String payload)throws Exception{handle(payload);}private void handle(String payload)throws Exception{var n=json.readTree(payload);if(!"ORDER_CONFIRMED".equals(n.path("eventType").asText()))return;String event=n.path("eventId").asText();String order=n.path("orderId").asText();if(event.isBlank()||order.isBlank())throw new IllegalArgumentException("ORDER_CONFIRMED missing eventId/orderId");service.processConfirmedEvent(UUID.fromString(event),UUID.fromString(order));}}
